import urllib.request,json
base="https://app.ontrackegy.com/saas/mobile/updates/"
for segment in ("latest.json","native/latest.json"):
 url=base+segment
 try:
  with urllib.request.urlopen(urllib.request.Request(url,headers={"Cache-Control":"no-cache"}),timeout=8) as response:
   data=json.load(response);meta=json.loads(data["payload"])
   print(json.dumps({"resource":segment,"status":response.status,"revision":meta.get("revision"),"version_code":meta.get("version_code"),"sha256":meta.get("sha256"),"file":meta.get("file")}))
 except Exception as error:print(json.dumps({"resource":segment,"error":str(error)[:160]}))
